create table if not exists public.kingman_scores (id bigint generated by default as identity primary key, player_name text not null, score integer not null default 0, stage integer not null default 1, mode text not null default 'normal', created_at timestamptz not null default now());
alter table public.kingman_scores enable row level security;
create policy "Public scores readable" on public.kingman_scores for select using (true);
create policy "Anyone can submit scores" on public.kingman_scores for insert with check (true);